-- Edel Solingen: SKUs das pinças inox (PIN-INX-PF/PO/PR) e fotos da navalha e das pinças inox
INSERT INTO "stored_files" ("id", "area", "fileName", "mimeType", "sizeBytes", "data", "createdAt")
SELECT gen_random_uuid(), 'products', 'edel-navalha-aco-standard.webp', 'image/webp', 25788, decode('', 'hex'), now()
WHERE NOT EXISTS (SELECT 1 FROM "stored_files" WHERE "fileName" = 'edel-navalha-aco-standard.webp');
INSERT INTO "product_images" ("id", "productId", "fileName", "mimeType", "isPrimary", "sortOrder", "createdAt")
SELECT gen_random_uuid(), p."id", 'edel-navalha-aco-standard.webp', 'image/webp', true, 0, now()
  FROM "products" p
 WHERE p."sku" = 'NAV-010' AND NOT EXISTS (SELECT 1 FROM "product_images" i WHERE i."productId" = p."id");
UPDATE "products" SET "sku" = 'PIN-INX-PF', "updatedAt" = now()
 WHERE "sku" = 'PIN-001' AND NOT EXISTS (SELECT 1 FROM "products" WHERE "sku" = 'PIN-INX-PF');
